function makeRandom() {
	let pat = patterns[5];
	pat.pattern = [];
	pat.colors = [];
	let plen = 2 * floor(random(5, 7)) + 1;
	for (let i = 0; i < plen; i++) {
		pat.pattern.push(0);
	}
	for (let i = 0; i < pat.pattern.length / 2; i++) {
		let sval = floor(random(1 + i, 5 + (3 * i)));
		let col;
		if (i % 2 == 0) col = color(random(100, 200), random(200), random(100, 200));
		else col = color(random(80), random(80), random(80));
		pat.pattern[i] = sval;
		pat.pattern[pat.pattern.length - 1 - i] = sval;
		pat.colors[i] = col;
		pat.colors[pat.pattern.length - 1 - i] = col;
	}
	pat.colors[floor(pat.pattern.length / 2)] = random(['black', 'white', 'darkgoldenrod']);
	pat.pattern[floor(pat.pattern.length / 2)] = random([1, 2]);
}

