function pickTartan() {
	pindex = menu.selected().substring(0, 1) - 1;
	if (pindex == 5) makeRandom();
	makePlaid();
}

function toggleExplain() {
	if (ebox.checked()) explain.style('visibility', 'visible');
	else explain.style('visibility', 'hidden');
}

function toggleZoom() {
	if (tzoom < 4) tzoom = 5;
	else tzoom = 0.9;
}

function newRandom() {
	menu.selected("6 - Generative Pattern 🧵")
	pindex = 5;
	makeRandom();
	makePlaid();
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "pattern."
// Color and weave patterns: https://www.kiltmakers.com/pub/media/brochures/pdf/Sett%20Guide.pdf
// Background on threadcount: https://www.tartanregister.gov.uk/threadcount
// Info on tartans: https://en.wikipedia.org/wiki/Tartan

let pindex = 0;
let swatch;
let zoom = 0.25;
let tzoom = 0.9;

function setup() {
	createCanvas(windowWidth, windowHeight);
	swatch = createGraphics(height, height);
	makeHTML();
	makePlaid();
}

function draw() {
	zoom = lerp(zoom, tzoom, 0.1);
	imageMode(CENTER);
	translate(width / 2, height / 2);
	scale(zoom);
	background(0);
	image(swatch, 0, 0);
}

function mouseWheel() {
	tzoom += event.delta / 100;
	tzoom = constrain(tzoom, 0.9, 5);
}

function makePlaid() {
	let sum = patterns[pindex].pattern.reduce((accumulator, currentValue) => accumulator + currentValue, 0);
	let rows = sum * patterns[pindex].density;
	let cols = sum * patterns[pindex].density;
	let dim = height / rows;
	let colors = patterns[pindex].colors;
	let pattern = patterns[pindex].pattern;
	let vpindex = 0;
	let vcindex = 0;
	let vcounter = 0;
	let hpindex = 0;
	let hcindex = 0;
	let hcounter = 0;
	swatch.background(0);
	swatch.push();
	swatch.translate(swatch.width / 2, swatch.height / 2);
	for (let row = 0; row < rows; row += 2) {
		let y = -height / 2 + row * dim;
		if (vcounter >= pattern[vpindex]) {
			vcounter = 0;
			vcindex = (vcindex + 1) % colors.length;
			vpindex = (vpindex + 1) % pattern.length;
		}
		vcounter += 1;
		hcounter = 0;
		hpindex = 0;
		hcindex = 0;
		for (let col = 0; col < cols; col += 2) {
			let x = -height / 2 + col * dim;
			if (hcounter >= pattern[hpindex]) {
				hcounter = 0;
				hcindex = (hcindex + 1) % colors.length;
				hpindex = (hpindex + 1) % pattern.length;
			}
			hcounter += 1;
			swatch.push();
			swatch.noStroke();
			swatch.translate(x, y);
			// Varying the stitch pattern creates the distinctive diagonal lines of a 2/2 "twill weave."
			// https://en.wikipedia.org/wiki/Twill
			if (row % 4 == col % 4) {
				swatch.fill(colors[hcindex]);
				swatch.rect(0, 0, dim, dim);
				swatch.fill(colors[hcindex]);
				swatch.rect(dim, 0, dim, dim);
				swatch.fill(colors[hcindex]);
				swatch.rect(dim, dim, dim, dim);
				swatch.fill(colors[vcindex]);
				swatch.rect(0, dim, dim, dim);
			} else {
				swatch.fill(colors[vcindex]);
				swatch.rect(0, 0, dim, dim);
				swatch.fill(colors[vcindex]);
				swatch.rect(dim, 0, dim, dim);
				swatch.fill(colors[vcindex]);
				swatch.rect(dim, dim, dim, dim);
				swatch.fill(colors[hcindex]);
				swatch.rect(0, dim, dim, dim);
			}
			swatch.pop();
		}
	}
	swatch.pop();
}

